SELECT p.id, p.dept_id, d.dept_code, d.dept_name, p.post_code, p.post_name, p.status, p.order_num, p.remark, p.create_time, p.update_time, p.create_user, p.update_user FROM sys_post p INNER JOIN sys_dept d ON p.dept_id = d.id
AND p.post_code LIKE CONCAT('%', #{query.postCode}, '%')
AND p.post_name LIKE CONCAT('%', #{query.postName}, '%')
AND d.dept_name LIKE CONCAT('%', #{query.deptName}, '%')
AND p.status = #{query.status}
ORDER BY ${orderBySql}

SELECT p.id, p.dept_id, d.dept_name, p.post_code, p.post_name, p.status FROM sys_post p INNER JOIN sys_dept d ON p.dept_id = d.id
AND p.status = #{status}
AND ( p.post_code LIKE CONCAT(#{keyword}, '%') OR p.post_name LIKE CONCAT(#{keyword}, '%') )
ORDER BY p.order_num ASC, p.id DESC LIMIT #{limit}

SELECT d.id FROM sys_dept d WHERE d.id IN
#{deptId}
AND d.status = 1 AND NOT EXISTS ( SELECT 1 FROM dept_closure dc INNER JOIN sys_dept a ON a.id = dc.ancestor_id WHERE dc.descendant_id = d.id AND dc.depth > 0 AND a.status = 0 )

SELECT p.dept_id, p.post_code FROM sys_post p WHERE (
(p.dept_id = #{pair.deptId} AND p.post_code = #{pair.postCode})
)
